// SPDX-License-Identifier: GPL-3.0-only
// Usina - the texture processor: grains, delay, tape and a room, from Emilie Gillet's 2021 granular/delay module (MIT;
// the port in src/fx/texture, generated by tools/port/port_texture.py and checked bit for bit against upstream).
// This class is what the module's main file (upstream beads.cc) is around that code, played the module's way:
//   - its knobs read through the module's own knob laws (pot_channel.h: smoothing, the PITCH knob's musical
//     intervals, the attenuverters' dead zone), once per block of 1/4000 s, as its control loop does;
//   - its input gain control (automatic, or a manual gain with the tape media's soft clipping), its processor, its
//     output clamped as the codec takes it, its 250 ms of silence when the media changes (the codec restarting);
//   - at its media's own rate - 48 kHz digital and clean tape, 32 kHz vintage, 24 kHz dirty tape, as the module runs
//     its codec - behind a sample-rate converter (src/dsp/Resampler.h) standing where the codec's filters stand. When
//     the host runs at that rate already, no converter: the processor's own samples.
// Ours, around it: the SEED input fed by the notes played or by the host's beats; the switch on/off, faded.
//
// Latency: the converters' and one block (latencySamples(); 12 samples at 48 kHz digital; about 3 ms at 24 kHz
// behind 44.1 kHz). It is not reported to the host: the texture is an effect the voices go through, and its dry part
// arrives that much later (docs/BACKLOG.md). No allocation in process(); prepare() sizes everything.
#pragma once
#include <memory>

namespace usina::fx {

class Texture {
public:
    enum Media { kDirtyTape = 0, kCleanTape, kVintage, kDigital, kNumMedia };   // (the processor's own order)
    enum SeedMode {
        kSeedInternal = 0,                               // the SEED button latched: DENSITY makes the grains
        kSeedNotes,                                      // the notes into the SEED input: grains while a note is held
        kSeedNotesDivided,                               // the notes as a clock, DENSITY dividing it
        kSeedHostClock,                                  // the host's beats as a clock (the delay in time with it)
        kNumSeedModes
    };

    // the panel, as knob positions 0..1 (the module's laws make them its values)
    struct Knobs {
        float time = 0.5f, size = 0.5f, shape = 0.5f, pitch = 0.5f;          // (pitch: 0.5 = unison)
        float timeAmt = 0.5f, sizeAmt = 0.5f, shapeAmt = 0.5f, pitchAmt = 0.5f;   // attenuverters (0.5 = none)
        float density = 0.5f, feedback = 0.0f, dryWet = 0.5f, reverb = 0.0f;
        float gain = 0.0f;                               // input gain: 0 = automatic, else manual (x1..x40)
        bool freeze = false, mono = false;
        int media = kDigital, seedMode = kSeedInternal;
    };

    Texture();
    ~Texture();

    void prepare(double hostRate, int maxBlock);         // (allocates: never on the audio thread)
    void reset();                                        // silent, emptied, as prepared
    // in place, on the voices; gate: the SEED input at the host's rate (a note held, a beat), or nullptr. on: the
    // switch - turned off, the texture fades out (20 ms) and stops; turned on, it starts empty and fades in
    void process(float* l, float* r, int n, const Knobs& k, const bool* gate, bool on);
    bool active() const;
    int latencySamples() const;                          // host samples, at the current media
    // the dry a bus mixes with it, in place, made as the texture's own path makes its signal (the same converters, no
    // module: latencySamples() later, filtered alike); false (untouched) when a plain delay matches it - the same
    // rate, or the texture off. Called once a block, before process, while it sits in a running bus
    bool dryTwin(float* l, float* r, int n);

    struct Impl;

private:
    std::unique_ptr<Impl> impl;
};

} // namespace usina::fx
